INSERT INTO `retail_battlepay_product` (`product_id`, `group_id`, `normal_price`, `current_price`, `product_type`, `flags`, `required_deliverable_id`, `eligibility`, `pmt_product_id`, `ordering`, `shop_flags`, `banner_type`, `display_file_data_id`, `display_model_scene_id`, `name_1`, `name_2`, `name_3`, `tooltip`, `instructions`, `display_flags`, `override_text_color`, `override_texture`, `override_background`, `disclaimer`, `nydus_link`, `battlepay_card_type`, `item_quantity`, `active`) VALUES
(248, 13, 100000, 100000, 2, 15, 0, 0, 25459, 87, 0, 0, 1616893, 10, 'Сумрак', '', 'Шустрый котенок, меняющий цвет в зависимости от настроения.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(253, 15, 250000, 250000, 3, 15, 0, 0, 25460, 88, 0, 0, 1616898, 78, 'Сияющая звездная пантара', '', 'Восприимчивый к токам энергии хищник с разоренной войной планеты Аргус, который может по желанию изменять цвет шкуры.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(80, 15, 250000, 250000, 3, 47, 0, 0, 366, 92, 0, 0, 841541, 81, 'Зачарованный волшебный дракончик', '', 'Отличитесь в любой ситуации, сидя верхом на этом меняющем цвета драконе.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(81, 13, 100000, 100000, 2, 47, 0, 0, 367, 91, 0, 0, 132620, 10, 'Щенок альтеракского мастифа', '', 'Покорите высочайшую вершину вместе с вашим верным щенком альтеракского мастифа.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(51, 13, 100000, 100000, 2, 47, 0, 0, 359, 94, 0, 0, 574806, 10, 'Душа Аспектов', '', 'Неукрощенный, но дружелюбный, этот золотистый дракон будет рассекать небеса вместе с вами.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(52, 13, 100000, 100000, 2, 47, 0, 0, 356, 95, 0, 0, 254652, 72, 'Рагнароша', '', 'Рагнароша очистит противников вашей команды в пламени!', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(54, 13, 100000, 100000, 2, 47, 0, 0, 360, 93, 0, 0, 666530, 10, 'Магматический котенок', '', 'Очарование этого магматического котенка обжигает.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(56, 13, 100000, 100000, 2, 47, 0, 0, 365, 92, 0, 0, 874857, 72, 'Цветущее древо', '', 'Это цветущее дерево позволит вам взрастить собственную коллекцию!', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(61, 15, 250000, 250000, 3, 47, 0, 0, 358, 98, 0, 0, 576138, 83, 'Сердце Аспектов', '', 'Тьма рассеется с приходом этого дракона, сияющего изнутри.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(108, 13, 100000, 100000, 2, 47, 0, 0, 15053, 90, 0, 0, NULL, 75, 'Арги', '', 'Веселая козочка из иного мира.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(128, 30, 200000, 200000, 5, 393884, 0, 0, 10830, 0, 0, 0, 1121394, 10, 'Жетон WoW', 'Жетон WoW', 'Жетон WoW можно продать другим игрокам за золото в аукционном доме. Покупатель впоследствии сможет использовать жетон, чтобы получить 30 дней игрового времени. Этот жетон нельзя обменять или использовать для своей учетной записи – он может быть только выставлен на продажу в аукционном доме.', '', '', NULL, NULL, NULL, NULL, '', '', 4, 0, 1),
(160, 13, 100000, 100000, 2, 47, 0, 0, 11694, 89, 0, 0, 1116250, 10, 'Ярколап', '', 'Котенок, преисполненный чародейской энергией, которому никак не сидится на месте.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(136, 15, 250000, 250000, 3, 47, 0, 0, 11432, 89, 0, 0, 1096090, 78, 'Мистический руноклык', '', 'Наполненный тайной магией, этот зверь покрыт мистическими рунами, преобразующими его мощь в крылья из чистой энергии.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(270, 13, 100000, 100000, 2, 15, 0, 0, 26776, 86, 0, 0, 1634262, 10, 'Тенёк', '', 'Хоть эта лисичка и прячется в тени, у нее золотое сердце.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(309, 15, 250000, 250000, 3, 15, 0, 0, 32990, 87, 0, 0, 1795322, 267, 'Шу-цзэнь, божественный страж', '', 'Шу-цзэнь, священный дар Света, считается символом большой удачи.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(325, 13, 100000, 100000, 2, 15, 0, 0, 37549, 84, 0, 0, 1998314, 10, 'Колотун', '', 'Колотун – маленький игривый вендиго, иногда спотыкающийся о собственные ножки. Весьма огромные, стоит признать.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(487, 138, 100000, 100000, 0, 15, 0, 0, 45890, 0, 0, 0, 2823166, 10, 'Маяк превращателя', '', 'Призывайте эфириала-превращателя, способного изменить ваш облик и превратить вас в случайное могущественное существо!

В течение определенного времени часть выручки с продаж будет направляться в призовой фонд World of Warcraft 2019 года. Подробнее читайте на сайте https://worldofwarcraft.com.', '', '', 130, NULL, NULL, NULL, '', '', 0, 0, 1),
(482, 15, 250000, 250000, 3, 15, 0, 0, 45832, 83, 0, 0, 2493157, 245, 'Сильверийский сновидец', '', 'Красивый пернатый дракон, рожденный из сна художницы, живущей в магическом городе Даларане.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(480, 15, 250000, 250000, 3, 15, 0, 0, 48330, 84, 0, 0, 2459601, 246, 'Хрюндель, благодатный свин', '', 'Пандарены со всего Азерота верят, что появление Хрюнделя сулит успех и процветание. И куда бы не занесли вас четыре ветра, его благословение принесет вам удачу в любых начинаниях.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(481, 15, 250000, 250000, 3, 15, 0, 0, 45833, 85, 0, 0, 2495963, 78, 'Космический лис', '', 'Поразительно смышленые существа, которые ценят дружбу и любят приключения.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(651, 15, 250000, 250000, 3, 15, 0, 0, 71371, 79, 0, 0, 3016707, 320, 'Пискун', '', 'Первая летучая крыса Азерота, парящая в небесах на нефритовых крыльях!', 'Никто не знает, где Пискун раздобыл свои невероятные нефритовые крылья. Может, он обхитрил саму Нефритовую змею? Теперь первая летучая крыса Азерота готова покинуть Пандарию, чтобы озорничать по всему миру.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(657, 13, 100000, 100000, 14, 15, 0, 0, 63290, 83, 0, 0, 3150958, 329, 'Дейзи', '', 'Дейзи не любит спешить и с удовольствием прокатится у вас на плечах.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(655, 15, 250000, 250000, 3, 15, 0, 0, 72292, 80, 0, 0, 2843118, 348, 'Паровой испепелитель', '', 'Грозный паровой испепелитель – настоящий механический ужас на паровом ходу. Хватайтесь за его железную чешую – и вперед, навстречу приключениям!', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(693, 15, 250000, 250000, 14, 15, 0, 0, 250961, 74, 0, 0, NULL, 383, 'Сапфировый огнесвет', '', 'Сапфировый огнесвет', 'Не вполне понятно, что привлекло сапфировых огнесветов на Азерот, но очевидно, что они горят ярче (и жарче!) чем все остальные птицы этого мира.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(696, 13, 100000, 100000, 14, 15, 0, 0, 251101, 74, 0, 0, NULL, 386, 'Грозный птенец', '', 'Грозный птенец', 'Темные крылья затуманят и поглотят все слабые умы. Просто потому что их владелец так мил!', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(698, 15, 250000, 250000, 14, 15, 0, 0, 264518, 69, 0, 0, NULL, 392, 'Грозный ворон', '', 'Грозный ворон', 'Исполненные ненавистью древнего бога, эти грозные вороны – самые преданные слуги араккоа.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(699, 139, 200000, 200000, 14, 15, 0, 0, 250981, 49, 0, 0, 3752758, 420, 'Комплект небесного наблюдателя', '', '', 'Этот комплект для трансмогрификации с ног до головы одевает вас в сияющую звездную пыль, перевитую магией подобно созвездиям Азерота.', '', 16, NULL, NULL, NULL, '', '', 9, 0, 1),
(659, 139, 200000, 200000, 14, 15, 0, 0, 64370, 50, 0, 0, 3071791, 420, 'Крылья летучего хамелеона', '', 'Очаруйте друзей и введите в ступор врагов с новым набором для трансмогрификации в стиле волшебных дракончиков Азерота. А чтобы ваш облик стал еще причудливее, в него также входят блестящие крылья и очаровательные усики!', 'Очаруйте друзей и введите в ступор врагов с новым набором для трансмогрификации в стиле волшебных дракончиков Азерота. А чтобы ваш облик стал еще причудливее, в него также входят блестящие крылья и очаровательные усики!', '', NULL, NULL, NULL, NULL, '', '', 9, 0, 1),
(664, 13, 100000, 100000, 14, 15, 0, 0, 74214, 81, 0, 0, NULL, 344, 'Маленький цийлинь удачи', '', 'Детеныш императорского цийлиня. По поверью, приносит своему владельцу удачу.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(665, 15, 250000, 250000, 14, 15, 0, 0, 74213, 81, 0, 0, NULL, 346, 'Императорский цийлинь', '', 'Любимцы древних правителей могу. Цийлинь станет верным и бесстрашным компаньоном любому наезднику.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(674, 15, 250000, 250000, 14, 15, 0, 0, 161260, 78, 0, 0, NULL, 371, 'Везунчик Юнь', '', '', 'Старейшины пандаренов утверждают, что Везунчик Юнь принесет благополучие любому, кто погладит его блестящую шкуру.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(704, 13, 100000, 100000, 14, 15, 0, 0, 301381, 77, 0, 0, NULL, 404, 'Блестяш', '', '', 'Едва вылупившись, Блестяш уже готов к приключениям. Но пару раз вздремнуть по пути тоже не повредит.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(701, 139, 150000, 150000, 14, 15, 0, 0, 301383, 48, 0, 0, 3922898, 258, 'Скорлупки малышей-мурлоков', '', '', 'Прежде чем покинуть свои скорлупки, головастики мурлоков хотят попутешествовать по миру на ваших плечах. Это украшение на спину доступно в трех расцветках, каждая со своим малышом-мурлоком.', '', NULL, NULL, 13261, NULL, '', '', 9, 0, 1),
(717, 15, 250000, 250000, 14, 15, 0, 0, 301384, 72, 0, 0, NULL, 423, 'Вэнь Ло, Берег Реки', '', '', 'Оседлайте Вэнь Ло, Берег Реки, и окиньте окрестности грозным взором. Этот внушительный транспорт поможет вам ощутить радость полета.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(725, 164, 500000, 500000, 15, 262223, 0, 0, 1963820, 1, 0, 0, 1530081, 10, 'Перенос 3 персонажей', '', 'Перенос 3 персонажей в другой игровой мир или учетную запись. Вы можете выполнить все три переноса сразу или совершить последовательно позже.', '', '', 2048, NULL, 27286, NULL, '', '', 0, 3, 1),
(728, 15, 250000, 250000, 14, 15, 0, 0, 436201, 73, 0, 0, NULL, 427, 'Солнечный мурмуровоз', '', '', 'Игривый солнечный мурмуровоз – самое пушистое средство передвижения на всем Азероте.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(1057, 13, 100000, 100000, 14, 15, 0, 0, 759075, 74, 0, 0, 4050685, 469, 'Муркастраза', '', '', 'Муркастраза – королева выводка мурлоков, вот уже много лет сражающаяся против своего злейшего врага Смертика.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(752, 139, 200000, 200000, 14, 15, 0, 0, 759079, 47, 0, 0, 4518147, 420, 'Регалии огнегривого феникса', '', '', 'Облачитесь в одеяния, украшенные чистым первородным огнем. Вы можете носить весь комплект целиком или сочетать его элементы с другими вариантами трансмогрификации из вашей коллекции.', '', 16, NULL, NULL, NULL, '', '', 9, 0, 1),
(809, 15, 250000, 250000, 14, 15, 0, 0, 61790, 70, 0, 0, NULL, 601, 'Заколдованный вечный змей', '', '', 'Заколдованный вечный змей позволяет начать цепочку заданий на получение комплекта для трансмогрификации "Одеяния вечного путника".', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(810, 13, 100000, 100000, 14, 15, 0, 0, 61830, 75, 0, 0, NULL, 602, 'Змееныш анимы', '', '', 'Жизнь даже самых крохотных созданий из Темных Земель зависит от анимы.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(724, 164, 250000, 250000, 15, 262223, 0, 0, 307522, 0, 0, 0, 1530081, 10, 'Перенос персонажа', '', 'Перенос персонажа в другой игровой мир или учетную запись.', '', '', 2048, NULL, 27286, NULL, '', '', 0, 1, 1),
(729, 164, 800000, 800000, 15, 262223, 0, 0, 1977379, 2, 0, 0, 1530081, 10, 'Перенос 6 персонажей', '', 'Перенос 6 персонажей в другой игровой мир или учетную запись. Вы можете использовать все шесть переносов сразу или совершить последовательно позже.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 6, 1),
(734, 13, 100000, 100000, 14, 15, 0, 0, 757641, 76, 0, 0, NULL, 476, 'Маленький Урсок', '', '', 'Прежде чем стать Диким богом и могучим защитником Азерота, игривый медвежонок Урсок с любопытством странствовал по Седым холмам.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(735, 166, 300000, 300000, 8, 262223, 0, 0, 757566, 20, 0, 0, 1126583, 10, 'Смена фракции', '', 'Сменить фракцию одного персонажа с Орды на Альянс или с Альянса на Орду.', '', '', 2048, NULL, 27246, NULL, '', '', 0, 1, 1),
(736, 166, 600000, 600000, 8, 262223, 0, 0, 1977405, 21, 0, 0, 1126583, 10, '3 смены фракции', '', 'Смена фракции 3 персонажей на противоположную (с Орды на Альянс или с Альянса на Орду). Можно выполнить все смены сразу или совершить последовательно позже.', '', '', 2048, NULL, 27246, NULL, '', '', 0, 3, 1),
(737, 166, 950000, 950000, 8, 262223, 0, 0, 1977406, 22, 0, 0, 1126583, 10, '6 смен фракции', '', 'Смена фракции 6 персонажей на противоположную (с Орды на Альянс или с Альянса на Орду). Можно выполнить все смены сразу или совершить последовательно позже.', '', '', NULL, NULL, NULL, NULL, '', '', 0, 6, 1),
(743, 15, 250000, 250000, 14, 15, 0, 0, 758606, 67, 0, 0, NULL, 470, 'Нефри Лучезарный провидец', '', '', 'Этот величественный дух кролика из Пандарии приносит радость и счастье, и его появление считается добрым знамением. Легенда гласит, что в его глазах можно увидеть самое счастливое мгновение вашей жизни – даже если оно еще не наступило.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(742, 15, 250000, 250000, 14, 15, 0, 0, 757642, 71, 0, 0, NULL, 479, 'Великий змей Пустоты', '', '', 'Искрясь чародейской энергией, великий змей Пустоты унесет вас к горизонту любого мироздания, в котором проходят ваши приключения.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(804, 15, 150000, 150000, 14, 15, 0, 0, 165538, 68, 0, 0, NULL, 635, 'Изумрудный внепространственный охотник', '', '', 'Эти существа произошли от вида, обладавшего естественной способностью к камуфляжу. Им позволяют перемещаться в пространстве таинственные энергии, превратившие Дренор в Запределье.', '', NULL, NULL, NULL, NULL, '', '', 0, 0, 1),
(828, 167, 250000, 250000, 10, 262223, 0, 0, 1148329, 40, 0, 0, 1126585, 10, 'Смена расы', '', 'Позволяет сменить расу одного персонажа в рамках текущей фракции. Также включает возможность сменить имя персонажа.

|cff66bbffСмену расы нельзя применить к персонажам, сменившим расу или фракцию в течение последних 3 дней. Услуга не действует для классов с только одной доступной расой в рамках одной фракции (охотники на демонов, пробудители). Могут действовать определенные ограничения. Подробности – на странице shop.battle.net.|r', '', '', 2048, NULL, 27250, NULL, '', '', 0, 1, 1),
